public class StreamBridgeException: UniffiException {
    StreamBridgeException() : base() {}
    StreamBridgeException(String @Message) : base(@Message) {}

    // Each variant is a nested class
    
    
    public class Stream : StreamBridgeException {
        // Members
        public string @code;
        public string @detail;

        // Constructor
        public Stream(
                string @code, 
                string @detail) : base(
                "@code" + "=" + @code+ ", " +
                "@detail" + "=" + @detail) {

            this.@code = @code;

            this.@detail = @detail;
        }
    }
    
    public class Closed : StreamBridgeException {
        public Closed() : base() {}
    }
    
    

    
}

class FfiConverterTypeStreamBridgeError : FfiConverterRustBuffer<StreamBridgeException>, CallStatusErrorHandler<StreamBridgeException> {
    public static FfiConverterTypeStreamBridgeError INSTANCE = new FfiConverterTypeStreamBridgeError();

    public override StreamBridgeException Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new StreamBridgeException.Stream(
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterString.INSTANCE.Read(stream));
            case 2:
                return new StreamBridgeException.Closed();
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeStreamBridgeError.Read()", value));
        }
    }

    public override int AllocationSize(StreamBridgeException value) {
        switch (value) {

            case StreamBridgeException.Stream variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@code)
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@detail);

            case StreamBridgeException.Closed variant_value:
                return 4;
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeStreamBridgeError.AllocationSize()", value));
        }
    }

    public override void Write(StreamBridgeException value, BigEndianStream stream) {
        switch (value) {
            case StreamBridgeException.Stream variant_value:
                stream.WriteInt(1);
                FfiConverterString.INSTANCE.Write(variant_value.@code, stream);
                FfiConverterString.INSTANCE.Write(variant_value.@detail, stream);
                break;
            case StreamBridgeException.Closed variant_value:
                stream.WriteInt(2);
                break;
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeStreamBridgeError.Write()", value));
        }
    }
}




